diff --git /dev/null b/tests/interface_exporting.rs
new file mode 100644
--- /dev/null
+++ b/tests/interface_exporting.rs
@@ -0,0 +1,203 @@
+use async_graphql::*;
+use serde::Deserialize;
+
+#[derive(SimpleObject)]
+struct ObjectA {
+    id: i32,
+    title: String,
+}
+
+#[derive(SimpleObject)]
+struct ObjectB {
+    id: i32,
+    title: String,
+}
+
+#[derive(Interface)]
+#[graphql(field(name = "id", type = "&i32"))]
+enum ImplicitInterface {
+    ObjectA(ObjectA),
+    ObjectB(ObjectB),
+}
+
+#[derive(Interface)]
+#[graphql(field(name = "title", type = "String"))]
+enum ExplicitInterface {
+    ObjectA(ObjectA),
+    ObjectB(ObjectB),
+}
+
+#[derive(Interface)]
+#[graphql(visible = false)]
+#[graphql(field(name = "title", type = "String"))]
+enum InvisibleInterface {
+    ObjectA(ObjectA),
+    ObjectB(ObjectB),
+}
+
+#[derive(SimpleObject)]
+struct ObjectC {
+    id: i32,
+    title: String,
+}
+
+#[derive(Interface)]
+#[graphql(field(name = "id", type = "&i32"))]
+enum UnreferencedInterface {
+    ObjectC(ObjectC),
+}
+
+
+#[derive(Union)]
+enum ObjectUnion {
+    ObjectA(ObjectA),
+    ObjectB(ObjectB),
+}
+
+struct Query;
+
+#[Object]
+impl Query {
+    async fn implicit(&self) -> ObjectUnion {
+        ObjectA {
+            id: 33,
+            title: "haha".to_string(),
+        }.into()
+    }
+
+    async fn explicit(&self) -> ExplicitInterface {
+        ObjectA {
+            id: 40,
+            title: "explicit".to_string(),
+        }.into()
+    }
+}
+
+fn build_schema() -> Schema<Query, EmptyMutation, EmptySubscription> {
+    Schema::build(Query, EmptyMutation, EmptySubscription)
+        .register_output_type::<ImplicitInterface>()
+        .register_output_type::<InvisibleInterface>()
+        .register_output_type::<UnreferencedInterface>()
+        .finish()
+}
+
+#[tokio::test]
+pub async fn test_interface_exports_interfaces_on_object_type() {
+    #[derive(Deserialize)]
+    struct QueryResponse {
+        #[serde(rename = "__type")]
+        ty: TypeResponse,
+    }
+
+    #[derive(Deserialize)]
+    struct TypeResponse {
+        name: String,
+        kind: String,
+        interfaces: Vec<InterfaceResponse>,
+    }
+
+    #[derive(Deserialize)]
+    struct InterfaceResponse {
+        name: String,
+    }
+
+    let schema = build_schema();
+
+    let resp: QueryResponse = from_value(
+        schema
+            .execute(r#"{ __type(name: "ObjectA") { name kind interfaces { name }} }"#)
+            .await
+            .into_result()
+            .unwrap()
+            .data,
+    )
+        .unwrap();
+
+    assert_eq!(resp.ty.name, "ObjectA");
+    assert_eq!(resp.ty.kind, "OBJECT");
+    assert!(resp.ty.interfaces.iter().any(|i| i.name == "ExplicitInterface"));
+    assert!(resp.ty.interfaces.iter().any(|i| i.name == "ImplicitInterface"));
+    assert!(!resp.ty.interfaces.iter().any(|i| i.name == "InvisibleInterface"));
+}
+
+#[tokio::test]
+pub async fn test_interface_exports_explicit_interface_type() {
+    let schema = build_schema();
+
+    let data = schema
+        .execute(r#"{ __type(name: "ExplicitInterface") { name kind } }"#)
+        .await
+        .into_result()
+        .unwrap()
+        .data;
+
+    assert_eq!(
+        data,
+        value!({
+            "__type": {
+                "name": "ExplicitInterface",
+                "kind": "INTERFACE",
+            }
+        })
+    );
+}
+
+#[tokio::test]
+pub async fn test_interface_exports_implicit_interface_type() {
+    let schema = build_schema();
+
+    let data = schema
+        .execute(r#"{ __type(name: "ImplicitInterface") { name kind } }"#)
+        .await
+        .into_result()
+        .unwrap()
+        .data;
+
+    assert_eq!(
+        data,
+        value!({
+            "__type": {
+                "name": "ImplicitInterface",
+                "kind": "INTERFACE",
+            }
+        })
+    );
+}
+
+#[tokio::test]
+pub async fn test_interface_no_export_invisible_interface_type() {
+    let schema = build_schema();
+
+    let data = schema
+        .execute(r#"{ __type(name: "InvisibleInterface") { name } }"#)
+        .await
+        .into_result()
+        .unwrap()
+        .data;
+
+    assert_eq!(
+        data,
+        value!({
+            "__type": null,
+        })
+    );
+}
+
+#[tokio::test]
+pub async fn test_interface_no_export_unreferenced_interface_type() {
+    let schema = build_schema();
+
+    let data = schema
+        .execute(r#"{ __type(name: "UnreferencedInterface") { name } }"#)
+        .await
+        .into_result()
+        .unwrap()
+        .data;
+
+    assert_eq!(
+        data,
+        value!({
+            "__type": null,
+        })
+    );
+}

problem_statement:
Interfaces not being exported via schema in Async GraphQL 3.x
## Expected Behavior
registering an interface to properly expose it via the __schema API.

## Actual Behavior
The interface is not accessible via the __schema API.

## Steps to Reproduce the Problem

1. I have two types that implement an interface
```rust
pub struct Question {
    pub video: Video,
}
#[Object]
impl Question {
    pub async fn id(&self) -> &VideoID {
        &self.video.id
    }
}

pub struct Response {
    pub video: Video,
}
#[Object]
impl Response {
    pub async fn id(&self) -> &VideoID {
        &self.video.id
    }
}
```
2. I have a union that that uses those 2 types
```rust
#[derive(Union)]
pub enum VideoUnion {
    Question(Question),
    Response(Response),
}
```
3. I have an interface registered via register_output_type.
```rust
#[derive(Interface)]
#[graphql(
    name = "Video",
    field(name = "id", type = "&VideoID"),
)]
pub enum VideoInterface {
    Question(Question),
    Response(Response),
}

// later in registering schema
schema.register_output_type::<VideoInterface>()
```

## Other information
1. the interface types DO get exposed via printing schema.sdl(), so it seems only that portion was perhaps updated with the split of registering output vs input types?
2. Note that all of my queries/endpoints return VideoUnion, Question, or Response and never "Video". 
3. this same setup works perfectly in 2.11.3

## Specifications

- Version: (only tested 3.0.7 and 3.0.11)
- Platform: macOS 10.15 / Rust 1.56
- Subsystem:

