+            Self {
+                my_val,
+                marker: PhantomData,
+            }
+        }
+    }
+
+    let schema = Schema::build(
+        MyQuery::<DefaultMyData>::new(),
+        EmptyMutation,
+        EmptySubscription,
+    )
+    .data(DefaultMyData {})
+    .finish();
+
+    assert_eq!(
+        schema.execute("{ obj { myVal } }").await.data,
+        value!({
+            "obj": {
+                "myVal": 42,
+            }
+        })
+    );
+}
