I am trying to do the same thing as you do, and this approach works:
```rust
use std::marker::PhantomData;
use async_graphql::{Object, SimpleObject, ComplexObject, Context, ID, Error, Result, Schema, EmptyMutation, EmptySubscription};

pub trait MyData: Send + Sync {}

struct DefaultMyData {}

impl MyData for DefaultMyData {}

pub struct MyQuery<D: MyData> {
    marker: PhantomData<D>,
}

#[Object]
impl<D> MyQuery<D> where D: 'static + MyData {
    #[graphql(skip)]
    pub fn new() -> Self {
        Self { marker: PhantomData }
    }

    async fn something(&self, ctx: &Context<'_>) -> Result<i64> {
        let my_data = ctx.data::<D>()?;
        Ok(42)
    }
}

pub fn main() {
    let my_data = DefaultMyData {};
    let schema = Schema::build(MyQuery::<DefaultMyData>::new(), EmptyMutation, EmptySubscription)
        .data(my_data)
        .finish();
    println!("{}", schema.sdl())
}
```

