+                        MetaType::Scalar {
+                            specified_by_url: Some(_),
+                            ..
+                        }
+                    )
+                })
+            {
+                return;
+            }
+
+            // Filter out oneOf directive from SDL if it is not used
+            if directive.name == "oneOf"
+                && !self
+                    .types
+                    .values()
+                    .any(|ty| matches!(ty, MetaType::InputObject { oneof: true, .. }))
+            {
+                return;
+            }
+
             writeln!(sdl, "{}", directive.sdl()).ok();
